// Recompute reading-time estimates for the novels from the actual prose.
// The formula lives in reading-time-core.mjs so the Sea chapter sync script
// measures chapters exactly the same way.
//
// The SEA row is report-only: Sea chapter frontmatter is generated by
// src/scripts/sea/sync-sea-chapters.ts (pnpm sea:sync), which is the only
// writer of those files.
//
// Run:  node src/scripts/compute-reading-time.mjs          (dry run, prints a table)
//       node src/scripts/compute-reading-time.mjs --write   (rewrites Lodge/Tsukinomi frontmatter)

import { existsSync, readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { CHARS_PER_MINUTE, measureMarkdown } from "./reading-time-core.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const WRITE = process.argv.includes("--write");

function measure(path) {
  const source = readFileSync(path, "utf8");
  return { source, ...measureMarkdown(source) };
}

function rewriteFrontmatter(source, { readingMinutes, wordsThai }) {
  let out = source;
  if (/^readingMinutes:\s*\d+/m.test(out)) {
    out = out.replace(/^readingMinutes:\s*\d+/m, `readingMinutes: ${readingMinutes}`);
  }
  if (/^wordsThai:\s*\d+/m.test(out)) {
    out = out.replace(/^wordsThai:\s*\d+/m, `wordsThai: ${wordsThai}`);
  }
  return out;
}

function run(label, dir, { reportOnly = false } = {}) {
  if (!existsSync(join(ROOT, dir))) {
    console.log(`\n==== ${label}: ${dir} not found, skipped ====`);
    return 0;
  }
  const files = readdirSync(join(ROOT, dir))
    .filter((f) => f.endsWith(".md"))
    .sort();
  let totalMinutes = 0;
  let totalChars = 0;
  console.log(`\n==== ${label} (${CHARS_PER_MINUTE} chars/min)${reportOnly ? " [report only]" : ""} ====`);
  for (const file of files) {
    const path = join(ROOT, dir, file);
    const m = measure(path);
    totalMinutes += m.readingMinutes;
    totalChars += m.readableChars;
    console.log(
      `${file.padEnd(34)} chars=${String(m.readableChars).padStart(6)} -> ${String(m.readingMinutes).padStart(4)} min`,
    );
    if (WRITE && !reportOnly) {
      writeFileSync(path, rewriteFrontmatter(m.source, m), "utf8");
    }
  }
  const h = Math.floor(totalMinutes / 60);
  const r = totalMinutes % 60;
  console.log(
    `TOTAL chars=${totalChars} minutes=${totalMinutes} (${h} ชม ${r} นาที ≈ ${(totalMinutes / 60).toFixed(1)}h)`,
  );
  return totalMinutes;
}

run("LODGE", "src/content/lodge/chapters");
run("TSUKINOMI", "src/content/tsukinomi/sections");
run("SEA", "src/content/the-sea-that-hung-above-the-world/chapters", { reportOnly: true });
console.log(`\n${WRITE ? "Frontmatter updated (Lodge/Tsukinomi only)." : "Dry run — pass --write to apply."}`);
